4	/* 将 size 向上对齐到最近的 2 的幂，用 &(size-1) 代替 % 取模 */
5	static uint32_t roundup_pow2(uint32_t n)
6	{
7	    n--;
8	    n |= n >> 1;  n |= n >> 2;  n |= n >> 4;
9	    n |= n >> 8;  n |= n >> 16;
10	    return n + 1;
11	}
12	
13	void ringbuf_init(ringbuf_t *rb, uint8_t *buf, uint32_t size)
14	{
15	    rb->buffer = buf;
16	    rb->size   = roundup_pow2(size);
17	    rb->head   = 0;
18	    rb->tail   = 0;
19	}
20	
21	uint32_t ringbuf_put(ringbuf_t *rb, const uint8_t *data, uint32_t len)
22	{
23	    uint32_t mask = rb->size - 1;
24	    uint32_t free = rb->size - (rb->head - rb->tail);
25	
26	    if (len > free) len = free;          /* 空间不够，只写能写下的部分 */
27	
28	    for (uint32_t i = 0; i < len; i++) {
29	        rb->buffer[(rb->head + i) & mask] = data[i];
30	    }

